private static final TypeCache<TypeCache.SimpleKey> PROXY_CACHE = new TypeCache.WithInlineExpunction<>(TypeCache.Sort.SOFT);

private Node exportInternalNode(final Node node) {
    final Optional<Class<? extends Node>> domClazz = getW3cNodeInterface(node.getClass());
    if(!domClazz.isPresent()) {
        throw new IllegalArgumentException("Provided node does not implement org.w3c.dom");
    }

    final Class<? extends Node> domInterface = domClazz.get();
    final Class<?> identityInterface;
    if (node instanceof StoredNode) {
        identityInterface = StoredNodeIdentity.class;
    } else if (node instanceof org.exist.dom.memtree.NodeImpl) {
        identityInterface = MemtreeNodeIdentity.class;
    } else {
        identityInterface = null;
    }

    final ClassLoader classLoader = getClass().getClassLoader();
    final TypeCache.SimpleKey cacheKey = new TypeCache.SimpleKey(domInterface,
            identityInterface != null ? identityInterface : Node.class);
    final Class<?> proxyClass = PROXY_CACHE.findOrInsert(classLoader, cacheKey, () -> {
        final Class<?>[] interfaceClasses = identityInterface != null
                ? new Class<?>[] { identityInterface }
                : new Class<?>[0];
        return new ByteBuddy()
                .subclass(domInterface)
                .implement(interfaceClasses)
                .method(any())
                .intercept(InvocationHandlerAdapter.of(new DOMMethodInterceptor(null)))
                .make()
                .load(classLoader)
                .getLoaded();
    });

    try {
        final Object proxy = proxyClass.getDeclaredConstructor().newInstance();
        InvocationHandlerAdapter.of(new DOMMethodInterceptor(node));
        return (Node) bindNode(proxy, node);
    } catch (final ReflectiveOperationException e) {
        throw new IllegalStateException("Unable to create DOM proxy for node: " + e.getMessage(), e);
    }
}

