package org.exist.extensions.exquery.restxq.impl.adapters;

import net.bytebuddy.ByteBuddy;
import net.bytebuddy.TypeCache;
import net.bytebuddy.description.modifier.Visibility;
import net.bytebuddy.implementation.InvocationHandlerAdapter;
import org.exist.dom.persistent.NodeHandle;
import org.exist.dom.persistent.NodeProxy;
import org.exist.xquery.value.Type;
import org.w3c.dom.Attr;
import org.w3c.dom.CDATASection;
import org.w3c.dom.Comment;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.ProcessingInstruction;
import org.w3c.dom.Text;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.util.Arrays;

import static net.bytebuddy.matcher.ElementMatchers.any;

/**
 * A NodeProxy Proxy which enhances NodeProxy
 * with a W3C DOM implementation by proxying to
 * its underlying typed node which is available
 * through NodeProxy.getNode()
 *
 * @author <a href="mailto:adam.retter@googlemail.com">Adam Retter</a>
 */
class DomEnhancingNodeProxyAdapter {

    private static final TypeCache<TypeCache.SimpleKey> PROXY_CACHE = new TypeCache.WithInlineExpunction<>(TypeCache.Sort.SOFT);

    private static final String HANDLER_FIELD_NAME = "$existNodeProxyHandler";

    public static NodeProxy create(final NodeProxy nodeProxy) {

        final Class<? extends Node>[] clazzes = getNodeClasses(nodeProxy);

        final ClassLoader classLoader = DomEnhancingNodeProxyAdapter.class.getClassLoader();
        final TypeCache.SimpleKey cacheKey = new TypeCache.SimpleKey(Arrays.asList(clazzes));
        final Class<?> proxyClass = PROXY_CACHE.findOrInsert(classLoader, cacheKey, () ->
                new ByteBuddy()
                        .subclass(NodeProxy.class)
                        .implement(clazzes)
                        .defineField(HANDLER_FIELD_NAME, InvocationHandler.class, Visibility.PUBLIC)
                        .method(any())
                        .intercept(InvocationHandlerAdapter.toField(HANDLER_FIELD_NAME))
                        .make()
                        .load(classLoader)
                        .getLoaded());

        try {
            final NodeProxy proxy = (NodeProxy) proxyClass
                    .getDeclaredConstructor(NodeHandle.class)
                    .newInstance(nodeProxy);
            proxyClass.getField(HANDLER_FIELD_NAME).set(proxy, new NodeDispatcher(nodeProxy));
            return proxy;
        } catch (final ReflectiveOperationException e) {
            throw new IllegalStateException("Unable to create DOM enhancing proxy for NodeProxy: " + e.getMessage(), e);
        }
    }

    private static Class<? extends Node>[] getNodeClasses(final NodeProxy nodeProxy) {
        return switch (nodeProxy.getType()) {
            case Type.DOCUMENT -> new Class[] { Document.class, Node.class };
            case Type.ELEMENT -> new Class[] { Element.class, Node.class };
            case Type.ATTRIBUTE -> new Class[] { Attr.class, Node.class };
            case Type.TEXT -> new Class[] { Text.class, Node.class };
            case Type.CDATA_SECTION -> new Class[] { CDATASection.class, Node.class };
            case Type.COMMENT -> new Class[] { Comment.class, Node.class };
            case Type.PROCESSING_INSTRUCTION -> new Class[] { ProcessingInstruction.class, Node.class };
            default -> new Class[] { Node.class };
        };
    }

    /**
     * Dispatches method calls made against the enhanced NodeProxy.
     *
     * Calls to methods declared by the W3C DOM {@link Node} interface (or one
     * of its sub-interfaces) are dispatched to the underlying typed node that
     * is available through {@link NodeProxy#getNode()}. All other calls are
     * dispatched to the wrapped {@link NodeProxy} itself.
     */
    public static class NodeDispatcher implements InvocationHandler {

        private final NodeProxy nodeProxy;

        public NodeDispatcher(final NodeProxy nodeProxy) {
            this.nodeProxy = nodeProxy;
        }

        @Override
        public Object invoke(final Object proxy, final Method method, final Object[] args) throws Throwable {
            final Object[] arguments = args != null ? args : new Object[0];
            final Object target = isMethodOnNode(method) ? nodeProxy.getNode() : nodeProxy;
            return method.invoke(target, arguments);
        }

        private static boolean isMethodOnNode(final Method method) {
            final Class<?> declaringClass = method.getDeclaringClass();

            //look for nodes
            if (declaringClass.equals(Node.class)) {
                return true;
            }

            //search parent interfaces
            for (final Class<?> iface : declaringClass.getInterfaces()) {
                if (iface.equals(Node.class)) {
                    return true;
                }
            }

            return false;
        }
    }
}

