503.     private static Sequence executeQuery(final DBBroker broker, final String query, final int expected, final String expectedResult) throws XPathException, SAXException, PermissionDeniedException {
504.         final XQuery xquery = broker.getBrokerPool().getXQueryService();
505.         final Sequence seq = xquery.execute(broker, query, null);
506.         assertEquals(expected, seq.getItemCount());
507. 
508.         if (expectedResult != null) {
509.             final Item item = seq.itemAt(0);
510.             final String value = serialize(broker, item);
511.             assertEquals(expectedResult, value);
512.         }
513.         return seq;
514.     }
515. 
516.     private static String serialize(final DBBroker broker, final Item item) throws SAXException, XPathException {
517.         final Serializer serializer = broker.borrowSerializer();
518.         try {
519.             final String value;
520.             if (Type.subTypeOf(item.getType(), Type.NODE)) {
521.                 value = serializer.serialize((NodeValue) item);
522.             } else {
523.                 value = item.getStringValue();
524.             }
