import org.exist.storage.BrokerPool;
import org.exist.storage.DBBroker;
import org.exist.storage.txn.TransactionManager;
import org.exist.storage.txn.Txn;
import org.exist.test.ExistEmbeddedServer;
import org.exist.collections.Collection;
import org.exist.util.MimeType;
import org.exist.util.StringInputSource;
import org.exist.xmldb.XmldbURI;
import org.exist.xquery.XQuery;
import org.exist.xquery.value.Item;
import org.exist.xquery.value.Sequence;
import org.exist.dom.persistent.NodeProxy;
import org.w3c.dom.Attr;
import org.w3c.dom.CDATASection;
import org.w3c.dom.Comment;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.ProcessingInstruction;
import org.w3c.dom.Text;

import java.lang.reflect.Method;
import java.util.Optional;

public class VerifyAdapter {

    private static Method createMethod;

    private static NodeProxy proxyFor(final Sequence seq) throws Exception {
        final Item item = seq.itemAt(0);
        if (!(item instanceof NodeProxy)) {
            throw new IllegalStateException("Expected NodeProxy but got " + item.getClass());
        }
        return (NodeProxy) createMethod.invoke(null, (NodeProxy) item);
    }

    private static void check(final String label, final boolean cond) {
        System.out.println((cond ? "PASS " : "FAIL ") + label);
        if (!cond) {
            FAILURES++;
        }
    }

    private static int FAILURES = 0;

    public static void main(final String[] args) throws Exception {
        // Access the package-private DomEnhancingNodeProxyAdapter.create(NodeProxy)
        final Class<?> adapterClass = Class.forName(
                "org.exist.extensions.exquery.restxq.impl.adapters.DomEnhancingNodeProxyAdapter");
        createMethod = adapterClass.getDeclaredMethod("create", NodeProxy.class);
        createMethod.setAccessible(true);

        final ExistEmbeddedServer server = new ExistEmbeddedServer(true, true);
        server.startDb();
        try {
            final BrokerPool pool = server.getBrokerPool();
            final TransactionManager transact = pool.getTransactionManager();
            final String xml = "<?pi-target pi-data?>" +
                    "<root attr=\"attrValue\">" +
                    "text-node" +
                    "<child/>" +
                    "<!-- a comment -->" +
                    "<![CDATA[cdata-content]]>" +
                    "</root>";
            try (final DBBroker broker = pool.get(Optional.of(pool.getSecurityManager().getSystemSubject()));
                 final Txn tx = transact.beginTransaction()) {
                final Collection root = broker.getOrCreateCollection(tx, XmldbURI.create(XmldbURI.ROOT_COLLECTION + "/verify"));
                broker.saveCollection(tx, root);
                broker.storeDocument(tx, XmldbURI.create("verify.xml"), new StringInputSource(xml), MimeType.XML_TYPE, root);
                transact.commit(tx);
            }

            try (final DBBroker broker = pool.get(Optional.of(pool.getSecurityManager().getSystemSubject()))) {
                final XQuery xquery = pool.getXQueryService();
                final String base = "doc('/db/verify/verify.xml')";

                // ELEMENT
                final NodeProxy elem = proxyFor(xquery.execute(broker, base + "/root", null));
                check("element is NodeProxy", elem instanceof NodeProxy);
                check("element is Element", elem instanceof Element);
                check("element is Node", elem instanceof Node);
                check("element getNodeName=root", "root".equals(((Element) elem).getNodeName()));
                check("element getTagName=root", "root".equals(((Element) elem).getTagName()));
                check("element getAttribute(attr)=attrValue", "attrValue".equals(((Element) elem).getAttribute("attr")));

                // ATTRIBUTE
                final NodeProxy attr = proxyFor(xquery.execute(broker, base + "/root/@attr", null));
                check("attribute is NodeProxy", attr instanceof NodeProxy);
                check("attribute is Attr", attr instanceof Attr);
                check("attribute getName=attr", "attr".equals(((Attr) attr).getName()));
                check("attribute getValue=attrValue", "attrValue".equals(((Attr) attr).getValue()));

                // TEXT
                final NodeProxy text = proxyFor(xquery.execute(broker, base + "/root/text()[1]", null));
                check("text is NodeProxy", text instanceof NodeProxy);
                check("text is Text", text instanceof Text);
                check("text getData=text-node", "text-node".equals(((Text) text).getData()));

                // COMMENT (newly mapped)
                final NodeProxy comment = proxyFor(xquery.execute(broker, base + "/root/comment()", null));
                check("comment is NodeProxy", comment instanceof NodeProxy);
                check("comment is Comment", comment instanceof Comment);
                check("comment getData=' a comment '", " a comment ".equals(((Comment) comment).getData()));

                // PROCESSING_INSTRUCTION (newly mapped)
                final NodeProxy pi = proxyFor(xquery.execute(broker, base + "/processing-instruction()", null));
                check("pi is NodeProxy", pi instanceof NodeProxy);
                check("pi is ProcessingInstruction", pi instanceof ProcessingInstruction);
                check("pi getTarget=pi-target", "pi-target".equals(((ProcessingInstruction) pi).getTarget()));

                // DOCUMENT
                final NodeProxy docNode = proxyFor(xquery.execute(broker, base, null));
                check("document is NodeProxy", docNode instanceof NodeProxy);
                check("document is Document", docNode instanceof Document);
            }
        } finally {
            server.stopDb();
        }

        System.out.println("----");
        if (FAILURES == 0) {
            System.out.println("ALL ADAPTER CHECKS PASSED");
        } else {
            System.out.println(FAILURES + " ADAPTER CHECK(S) FAILED");
            System.exit(1);
        }
    }
}

