27. package org.exist.extensions.exquery.restxq.impl.adapters;
28. 
29. import net.bytebuddy.ByteBuddy;
30. import net.bytebuddy.TypeCache;
31. import net.bytebuddy.description.modifier.Visibility;
32. import net.bytebuddy.implementation.InvocationHandlerAdapter;
33. import org.exist.dom.persistent.NodeHandle;
34. import org.exist.dom.persistent.NodeProxy;
35. import org.exist.xquery.value.Type;
36. import org.w3c.dom.Attr;
37. import org.w3c.dom.CDATASection;
38. import org.w3c.dom.Comment;
39. import org.w3c.dom.Document;
40. import org.w3c.dom.Element;
41. import org.w3c.dom.Node;
42. import org.w3c.dom.ProcessingInstruction;
43. import org.w3c.dom.Text;
44. 
45. import java.lang.reflect.InvocationHandler;
46. import java.lang.reflect.Method;
47. import java.util.Arrays;
48. 
49. import static net.bytebuddy.matcher.ElementMatchers.any;
50. 
51. /**
52.  * A NodeProxy Proxy which enhances NodeProxy
53.  * with a W3C DOM implementation by proxying to
54.  * its underlying typed node which is available
55.  * through NodeProxy.getNode()
56.  *
57.  * @author <a href="mailto:adam.retter@googlemail.com">Adam Retter</a>
58.  */
59. class DomEnhancingNodeProxyAdapter {
60. 
61.     private static final TypeCache<TypeCache.SimpleKey> PROXY_CACHE = new TypeCache.WithInlineExpunction<>(TypeCache.Sort.SOFT);
62. 
63.     private static final String HANDLER_FIELD_NAME = "$existNodeProxyHandler";
64. 
65.     public static NodeProxy create(final NodeProxy nodeProxy) {
66. 
67.         final Class<? extends Node>[] clazzes = getNodeClasses(nodeProxy);
68. 
69.         final ClassLoader classLoader = DomEnhancingNodeProxyAdapter.class.getClassLoader();
70.         final TypeCache.SimpleKey cacheKey = new TypeCache.SimpleKey(Arrays.asList(clazzes));
71.         final Class<?> proxyClass = PROXY_CACHE.findOrInsert(classLoader, cacheKey, () ->
72.                 new ByteBuddy()
73.                         .subclass(NodeProxy.class)
74.                         .implement(clazzes)
75.                         .defineField(HANDLER_FIELD_NAME, InvocationHandler.class, Visibility.PUBLIC)
76.                         .method(any())
77.                         .intercept(InvocationHandlerAdapter.toField(HANDLER_FIELD_NAME))
78.                         .make()
79.                         .load(classLoader)
80.                         .getLoaded());
81. 
82.         try {
83.             final NodeProxy proxy = (NodeProxy) proxyClass
84.                     .getDeclaredConstructor(NodeHandle.class)
85.                     .newInstance(nodeProxy);
86.             proxyClass.getField(HANDLER_FIELD_NAME).set(proxy, new NodeDispatcher(nodeProxy));
87.             return proxy;
88.         } catch (final ReflectiveOperationException e) {
89.             throw new IllegalStateException("Unable to create DOM enhancing proxy for NodeProxy: " + e.getMessage(), e);
90.         }
91.     }
92. 
93.     private static Class<? extends Node>[] getNodeClasses(final NodeProxy nodeProxy) {
94.         return switch (nodeProxy.getType()) {
95.             case Type.DOCUMENT -> new Class[] { Document.class, Node.class };
96.             case Type.ELEMENT -> new Class[] { Element.class, Node.class };
97.             case Type.ATTRIBUTE -> new Class[] { Attr.class, Node.class };
98.             case Type.TEXT -> new Class[] { Text.class, Node.class };
99.             case Type.CDATA_SECTION -> new Class[] { CDATASection.class, Node.class };
100.             case Type.COMMENT -> new Class[] { Comment.class, Node.class };
101.             case Type.PROCESSING_INSTRUCTION -> new Class[] { ProcessingInstruction.class, Node.class };
102.             default -> new Class[] { Node.class };
103.         };
104.     }
105. 
106.     /**
107.      * Dispatches method calls made against the enhanced NodeProxy.
108.      *
109.      * Calls to methods declared by the W3C DOM {@link Node} interface (or one
110.      * of its sub-interfaces) are dispatched to the underlying typed node that
111.      * is available through {@link NodeProxy#getNode()}. All other calls are
112.      * dispatched to the wrapped {@link NodeProxy} itself.
113.      */
114.     public static class NodeDispatcher implements InvocationHandler {
115. 
116.         private final NodeProxy nodeProxy;
117. 
118.         public NodeDispatcher(final NodeProxy nodeProxy) {
119.             this.nodeProxy = nodeProxy;
120.         }
121. 
122.         @Override
123.         public Object invoke(final Object proxy, final Method method, final Object[] args) throws Throwable {
124.             final Object[] arguments = args != null ? args : new Object[0];
125.             final Object target = isMethodOnNode(method) ? nodeProxy.getNode() : nodeProxy;
126.             return method.invoke(target, arguments);
127.         }
128. 
129.         private static boolean isMethodOnNode(final Method method) {
130.             final Class<?> declaringClass = method.getDeclaringClass();
131. 
132.             //look for nodes
133.             if (declaringClass.equals(Node.class)) {
134.                 return true;
135.             }
136. 
137.             //search parent interfaces
138.             for (final Class<?> iface : declaringClass.getInterfaces()) {
139.                 if (iface.equals(Node.class)) {
140.                     return true;
141.                 }
142.             }
143. 
144.             return false;
145.         }
146.     }
147. }
